import streamlit as stimport time# ==========================================# 1. DESIGN OG OPSÆTNING# ==========================================# Sætter sidens titel og ikon i browser-fanenst.set_page_config(page_title="Københavner-Quizzen", page_icon="🥨", layout="centered")# Lidt avanceret: Custom CSS til at gøre knapper og tekst "lækkert" og modernest.markdown("""    <style>    div.stButton > button:first-child {        background-color: #ff4b4b;        color: white;        border-radius: 10px;        height: 3em;        width: 100%;        font-weight: bold;        font-size: 16px;    }    div.stButton > button:hover {        background-color: #ff3333;        border-color: #ff3333;    }    .level-text {        font-size: 24px;        font-weight: bold;        color: #ff4b4b;    }    </style>""", unsafe_allow_html=True)# ==========================================# 2. VORES DATA (LISTER OG DICTS FRA CHEAT SHEET)# ==========================================# Vi bruger en Liste, der indeholder Dictionaries (ordbøger) til hvert spørgsmål.sporgsmal_data = [    {        "spm": "Hvor mange cykler er der cirka i København i forhold til indbyggere?",        "muligheder": ["Færre cykler end indbyggere", "Lige så mange cykler som indbyggere", "Flere cykler end indbyggere"],        "svar": "Flere cykler end indbyggere",        "fact": "Faktisk er der over 5 gange så mange cykler, som der er biler i indre by!"    },    {        "spm": "Hvilket år blev forlystelsesparken Tivoli grundlagt?",        "muligheder": ["1843", "1899", "1912", "1955"],        "svar": "1843",        "fact": "Tivoli er verdens næstældste forlystelsespark. Den ældste er Bakken!"    },    {        "spm": "Hvad hedder den berømte bro, der forbinder Nyhavn med Christianshavn?",        "muligheder": ["Langebro", "Inderhavnsbroen (Kyssebroen)", "Knippelsbro", "Dronning Louises Bro"],        "svar": "Inderhavnsbroen (Kyssebroen)",        "fact": "Den kaldes Kyssebroen, fordi de to bro-dele mødes på midten som et kys."    },    {        "spm": "Hvor høj er Rundetårn (hvis man måler til udsigtsplatformen)?",        "muligheder": ["15 meter", "35 meter", "55 meter", "85 meter"],        "svar": "35 meter",        "fact": "Selvom tårnet kun er knap 35 meter højt, er sneglegangen derop hele 209 meter lang."    },    {        "spm": "Hvem har grundlagt København ifølge den mest kendte myte?",        "muligheder": ["Christian 4.", "Biskop Absalon", "Harald Blåtand", "Dronning Margrethe 1."],        "svar": "Biskop Absalon",        "fact": "Absalon byggede en borg på Slotsholmen i 1167, hvilket ofte regnes for byens grundlæggelse."    }]# ==========================================# 3. HUKOMMELSE (SESSION STATE)# ==========================================# Streamlit genindlæser hele koden, hver gang du trykker på en knap. # Derfor skal vi gemme score og spørgsmåls-nummer i 'session_state', så det ikke nulstilles.if 'score' not in st.session_state:    st.session_state.score = 0if 'index' not in st.session_state:    st.session_state.index = 0if 'svar_afgivet' not in st.session_state:    st.session_state.svar_afgivet = False# ==========================================# 4. FUNKTIONER TIL LOGIK (FRA CHEAT SHEET)# ==========================================# En funktion til at udregne brugerens 'Level' med if/elif/else[cite: 1, 2]def find_level(point):    if point == 0:        return "Forvildet Turist 🗺️"    elif point <= 2:        return "Jysk Tilflytter 🚜"    elif point <= 4:        return "Vesterbro-Hipster ☕"    else:        return "Ægte Københavner 👑"# ==========================================# 5. BRUGERFLADEN (DET DU SER PÅ SKÆRMEN)# ==========================================st.title("🚲 Den Store Københavner-Quiz")st.write("Test din viden om Danmarks hovedstad og level op fra *Forvildet Turist* til *Ægte Københavner*!")# --- SIDEBAR (Menu ude i venstre side) ---with st.sidebar:    st.header("🏆 Din Status")        # Udregn og vis nuværende level    nuvaerende_level = find_level(st.session_state.score)    st.markdown(f"<p class='level-text'>{nuvaerende_level}</p>", unsafe_allow_html=True)        st.metric(label="Point", value=f"{st.session_state.score} / {len(sporgsmal_data)}")        st.divider()    if st.button("🔄 Nulstil Quiz"):        st.session_state.score = 0        st.session_state.index = 0        st.session_state.svar_afgivet = False        st.rerun()# --- HOVEDOMRÅDE: SPØRGSMÅL ELLER AFSLUTNING ---# Hvis vi ikke har stillet alle spørgsmål endnuif st.session_state.index < len(sporgsmal_data):        # Hent det nuværende spørgsmål fra listen    nuvaerende_spm = sporgsmal_data[st.session_state.index]        # Vis hvor langt vi er (Progress bar)    st.progress(st.session_state.index / len(sporgsmal_data))    st.caption(f"Spørgsmål {st.session_state.index + 1} af {len(sporgsmal_data)}")        # Udskriv selve spørgsmålet    st.subheader(nuvaerende_spm["spm"])        # Gem brugerens valg i en variabel (radio-knapper)    bruger_valg = st.radio("Vælg dit svar:", nuvaerende_spm["muligheder"], key=f"radio_{st.session_state.index}")        st.divider()    # Hvis der ikke er svaret endnu, vis "Svar" knappen    if not st.session_state.svar_afgivet:        if st.button("Afgiv svar"):            st.session_state.svar_afgivet = True            st.rerun() # Får siden til at opdatere med det samme                # Hvis der ER svaret, så vis resultatet og "Næste" knappen    else:        # Tjekker om svaret er korrekt (Logik: == )[cite: 2]        if bruger_valg == nuvaerende_spm["svar"]:            st.success("Helt rigtigt! 🎉")            st.info(f"**Vidste du?** {nuvaerende_spm['fact']}")                        # Giv point (men kun hvis det er første gang knappen vises for dette spørgsmål)            if 'givet_point' not in st.session_state:                st.session_state.score += 1                st.session_state.givet_point = True                if st.session_state.score == len(sporgsmal_data): # Fuld plade!                    st.balloons()        else:            st.error(f"Desværre! Det rigtige svar var: **{nuvaerende_spm['svar']}**")            st.info(f"**Vidste du?** {nuvaerende_spm['fact']}")            st.session_state.givet_point = True # Sikrer vi ikke giver point                # Knap til at gå videre        if st.button("Gå til næste spørgsmål ➡️"):            # Nulstil logik til næste spørgsmål            st.session_state.index += 1            st.session_state.svar_afgivet = False            del st.session_state.givet_point # Glem at vi gav point, så vi er klar igen            st.rerun()# Hvis alle spørgsmål er besvaretelse:    st.progress(100)    st.header("Tillykke! Du har gennemført quizzen. 🏁")        slut_level = find_level(st.session_state.score)    st.subheader(f"Du endte som: {slut_level}")        st.write(f"Du fik **{st.session_state.score}** rigtige ud af **{len(sporgsmal_data)}** mulige.")        if st.session_state.score == len(sporgsmal_data):        st.success("Fejlfri! Du kan roligt kalde dig selv for bykonge/bydronning!")    elif st.session_state.score > 2:        st.warning("Godt gået! Du kender byen rimelig godt.")    else:        st.error("Det var ikke så godt. Du må hellere tage en tur med Havnebussen og lære byen at kende.")            if st.button("Prøv igen"):        st.session_state.score = 0        st.session_state.index = 0        st.session_state.svar_afgivet = False        st.rerun()